head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elw_recv_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF05906.xml";
scwin.vBzTpCd;
scwin.TR_JOB = 'I';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var url = "/ElwListedReceive.do?method=listElwListDdReg&inputMessageId=ELW_LISTING_PROC_INOUT";
    url += "&LIST_BZ_TP_CD=" + scwin.vBzTpCd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_save = function() {
    var k = 0;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if (dts_List.getCellData(i, "CHECK") == "T") {
            k++;
        }
    }
    if (k == 0) {
        $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_LIST_DD)) {
        $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return;
    }
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if (dts_List.getCellData(i, "CHECK") == "T") // 이것이 여태 빠져 있었네. ^^;;;   jackal_ko_10.06.15

        {
            dts_List.setCellData(i, "LIST_DD", $c.stf.getObjectValue(edt_LIST_DD));
            dts_List.setCellData(i, "LIST_PROCS_STAT_CD", ELW_RECV_PROC_CD_13);
        }
    }
    //dts_Isu.UserStatus(1) = TB_JOB_UPDATE;

    //alert('[dtsObj]'+dtsObj.text);
    trs_Save.Action = $c.lc.fn_encodeNSession("/ElwListedReceive.do?method=saveElwListDd&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_save();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_LIST_DD_onclick = function() {
    popUpCalendar2(edt_LIST_DD);
};
scwin.grd_List_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.elw.fn_setCheckBox(grd_List, dts_List, bCheck);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt.setValue("총 " + dts_List.getTotalRow() + " 건");
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    await $c.frame.CloseFrame();
    scwin.fn_parentRefresh(); // 목록 다시 조회

};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    var parentWin = $c.frame.path("../");
    scwin.vBzTpCd = parentWin.fn_getbzTpCd();
    scwin.fn_list_sync();
};
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
